# The real fix: /products never used ProductMeta at all, it had its
# own separate custom price display with no rating shown anywhere.
# Replaced with the shared ProductMeta component.
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\products\ProductsClient.tsx"), $bytes)
Write-Host "UPDATED: src\app\products\ProductsClient.tsx" -ForegroundColor Green
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan